import{_ as e,o,c as i,aa as n}from"./chunks/framework.BAs_AphD.js";const a="/buildary-help-preview/media/en/tickets/en_exporty.png",s="/buildary-help-preview/media/en/tickets/en_exporty_vybrane.png",r="/buildary-help-preview/media/en/tickets/en_ukol_stazeni.png",w=JSON.parse('{"title":"Exports","description":"","frontmatter":{"title":"Exports","wiki":"en:tickets:exports"},"headers":[],"relativePath":"en/tickets/exports.md","filePath":"en/tickets/exports.md","lastUpdated":1794388980000}'),l={name:"en/tickets/exports.md"};function d(c,t,p,h,g,m){return o(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="exports" tabindex="-1">Exports <a class="header-anchor" href="#exports" aria-label="Permalink to &quot;Exports&quot;">​</a></h1><p>Buildary offers several options for exporting tickets and for choosing the output format. Exports are available in PDF or XLS format, and the content of the downloaded data can be customized.</p><figure class="shot" style="--w:500px;"><img src="'+a+'" alt="Exports" width="400" loading="lazy"></figure><p><strong>1/</strong> To <strong>download all tickets currently displayed in the grid</strong>, use the <strong>Export</strong> button above the ticket grid. There are 4 export options:</p><ul><li><strong>Export Excel</strong> ⇒ downloads an Excel workbook containing all tickets currently displayed in the grid, listed one below another, with a complete list of parameters in columns, regardless of which columns are selected in the grid.</li><li><strong>Export Excel with Photos</strong> ⇒ downloads a ZIP file containing the same Excel workbook as above, plus all images / photos attached to the relevant tickets (non-image attachments are not downloaded). <strong>!IMPORTANT! Images embedded in Statements are not included in this file</strong>.</li><li><strong>Export PDF</strong> ⇒ downloads a PDF file, with each ticket starting on a new page. All attachments associated with the tickets, whether added as attachments or included in Statements, are included as electronic attachments in the PDF file and can be accessed via the paperclip icon in the PDF editor being used (Adobe Acrobat / PDF-XChange Editor, etc.).</li><li><strong>Export PDF without Statements</strong> ⇒ downloads a PDF file, with each ticket starting on a new page, but the Statement thread is omitted, including its attachments.</li></ul><figure class="shot" style="--w:500px;"><img src="'+s+'" alt="Bulk Selection Export" width="150" loading="lazy"></figure><p><strong>2/</strong> To <strong>download only selected tickets</strong> displayed in the grid, you can select the required items by checking the checkbox at the beginning of each row and then use the <strong>Bulk Operations</strong> button for the selected items. Proceed in the same way as described in point 1/.</p><figure class="shot" style="--w:500px;"><img src="'+r+'" alt="Ticket Export" width="500" loading="lazy"></figure><p><strong>3/</strong> A <strong>ticket can also be downloaded individually in PDF format</strong>, either directly from Ticket Details (Edit Ticket) or from the Kanban view. The option to download the ticket is located in the top-right corner under the vertical Three-Dot Menu.</p>',9)])])}const x=e(l,[["render",d]]);export{w as __pageData,x as default};
